import { expr, sanitizeName, tsLabelToTfLabel } from "../../engine/tf/index.js";
const CATEGORY = "elementum_category";
const GROUP = "elementum_group";
const USER = "elementum_user";
const CLOUD_LINK = "elementum_cloudlink";
const EMAIL_ALIAS = "elementum_email_alias";
const PHONE_PROVIDER = "elementum_phone_provider";
function secretValue(value, variables) {
    if (value.__kind === "redactedOrganizationSecret")
        return undefined;
    variables.set(value.variable, { kind: "variable", label: value.variable, attrs: {
            sensitive: true,
            description: `Sensitive organization credential. Supply as TF_VAR_${value.variable}.`,
        } });
    return expr.variable(value.variable);
}
function credentialsValue(value, variables) {
    if (value.redacted !== undefined)
        return undefined;
    if (value.bearerToken !== undefined) {
        const token = secretValue(value.bearerToken.token, variables);
        return token === undefined ? undefined : { bearer_token: { token } };
    }
    if (value.password !== undefined) {
        const password = secretValue(value.password.password, variables);
        return password === undefined ? undefined : { password: { username: value.password.username, password } };
    }
    if (value.privateKey !== undefined)
        return { private_key: { username: value.privateKey.username } };
    if (value.serviceAccount !== undefined) {
        const json = secretValue(value.serviceAccount.json, variables);
        return json === undefined ? undefined : { service_account: { json } };
    }
    const clientSecret = secretValue(value.externalOauth.clientSecret, variables);
    const password = value.externalOauth.password === undefined ? undefined : secretValue(value.externalOauth.password, variables);
    if (clientSecret === undefined || (value.externalOauth.password !== undefined && password === undefined))
        return undefined;
    return { external_oauth: {
            client_id: value.externalOauth.clientId,
            client_secret: clientSecret,
            url: value.externalOauth.url,
            ...(value.externalOauth.username !== undefined && { username: value.externalOauth.username }),
            ...(password !== undefined && { password }),
        } };
}
const schedule = (value) => value === undefined ? undefined : { interval: value.interval, unit: value.unit };
export function organizationToTf(organization, ctx) {
    const blocks = [];
    const variables = new Map();
    for (const [key, category] of Object.entries(organization.categories)) {
        const attrs = { name: category.name };
        if (category.color !== undefined)
            attrs["color"] = category.color;
        if (category.icon !== undefined)
            attrs["icon"] = category.icon;
        if (category.description !== undefined)
            attrs["description"] = category.description;
        blocks.push({ kind: "resource", type: CATEGORY, label: tsLabelToTfLabel(key), attrs });
    }
    for (const [key, group] of Object.entries(organization.groups)) {
        const attrs = { name: group.name };
        for (const [wire, value] of [
            ["approver", group.approver], ["assignable", group.assignable], ["mentionable", group.mentionable],
            ["watchable", group.watchable], ["dynamic", group.dynamic],
        ])
            if (value !== undefined)
                attrs[wire] = value;
        if (group.tags !== undefined)
            attrs["tags"] = [...group.tags];
        if (group.members !== undefined) {
            attrs["members"] = group.members.map(({ email }) => {
                const label = sanitizeName(email);
                ctx.orgRefs.rawLookup(USER, label, email);
                return expr.dataAttr(USER, label, ["id"]);
            });
        }
        blocks.push({ kind: "resource", type: GROUP, label: tsLabelToTfLabel(key), attrs });
    }
    for (const [key, cloudLink] of Object.entries(organization.cloudLinks)) {
        const resourceVariables = new Map();
        const attrs = { name: cloudLink.name, type: cloudLink.type };
        if (cloudLink.cache !== undefined)
            attrs["cache"] = cloudLink.cache;
        if (cloudLink.encryptCache !== undefined)
            attrs["encrypt_cache"] = cloudLink.encryptCache;
        if (cloudLink.usageType !== undefined)
            attrs["usage_type"] = cloudLink.usageType;
        if (cloudLink.credentials !== undefined) {
            const credentials = credentialsValue(cloudLink.credentials, resourceVariables);
            if (credentials === undefined) {
                ctx.diagnostics?.push(`cloudLinks.${key}: credentials are write-only; replace redactedSecret(...) with secret(...) before this CloudLink can be managed`);
                continue;
            }
            attrs["credentials"] = credentials;
        }
        if (cloudLink.api !== undefined)
            attrs["api_config"] = { base_url: cloudLink.api.baseUrl };
        if (cloudLink.bigQuery !== undefined)
            attrs["bigquery_config"] = {
                project_id: cloudLink.bigQuery.projectId, dataset_id: cloudLink.bigQuery.datasetId,
                location: cloudLink.bigQuery.location, read_only: cloudLink.bigQuery.readOnly,
                ...(schedule(cloudLink.bigQuery.schedule) !== undefined && { schedule: schedule(cloudLink.bigQuery.schedule) }),
            };
        if (cloudLink.databricks !== undefined)
            attrs["databricks_config"] = {
                hostname: cloudLink.databricks.hostname, port: cloudLink.databricks.port,
                database: cloudLink.databricks.database, schema: cloudLink.databricks.schema,
                read_only: cloudLink.databricks.readOnly,
                ...(schedule(cloudLink.databricks.schedule) !== undefined && { schedule: schedule(cloudLink.databricks.schedule) }),
            };
        if (cloudLink.elementumSnowflake !== undefined) {
            if (typeof cloudLink.elementumSnowflake.region !== "string") {
                ctx.diagnostics?.push(`cloudLinks.${key}: region is input-only; replace unavailableValue("region") before this CloudLink can be managed`);
                continue;
            }
            attrs["elementum_snowflake_config"] = {
                region: cloudLink.elementumSnowflake.region, warehouse_size: cloudLink.elementumSnowflake.warehouseSize,
                ...(schedule(cloudLink.elementumSnowflake.schedule) !== undefined && { schedule: schedule(cloudLink.elementumSnowflake.schedule) }),
            };
        }
        if (cloudLink.snowflake !== undefined)
            attrs["snowflake_config"] = {
                url: cloudLink.snowflake.url, account: cloudLink.snowflake.account,
                warehouse: cloudLink.snowflake.warehouse, role: cloudLink.snowflake.role,
                read_only: cloudLink.snowflake.readOnly,
                ...(cloudLink.snowflake.createDatabase !== undefined && { create_database: cloudLink.snowflake.createDatabase }),
                ...(cloudLink.snowflake.createSchema !== undefined && { create_schema: cloudLink.snowflake.createSchema }),
                ...(cloudLink.snowflake.gzip !== undefined && { gzip: cloudLink.snowflake.gzip }),
                ...(schedule(cloudLink.snowflake.schedule) !== undefined && { schedule: schedule(cloudLink.snowflake.schedule) }),
            };
        blocks.push({ kind: "resource", type: CLOUD_LINK, label: tsLabelToTfLabel(key), attrs });
        for (const [name, block] of resourceVariables)
            variables.set(name, block);
    }
    for (const [key, emailAlias] of Object.entries(organization.emailAliases)) {
        blocks.push({ kind: "resource", type: EMAIL_ALIAS, label: tsLabelToTfLabel(key), attrs: { alias: emailAlias.alias } });
    }
    for (const [key, phoneProvider] of Object.entries(organization.phoneProviders)) {
        const resourceVariables = new Map();
        const accountId = secretValue(phoneProvider.twilio.accountId, resourceVariables);
        const authToken = secretValue(phoneProvider.twilio.authToken, resourceVariables);
        if (accountId === undefined || authToken === undefined) {
            ctx.diagnostics?.push(`phoneProviders.${key}: Twilio credentials are write-only; replace redactedSecret(...) with secret(...) before this provider can be managed`);
            continue;
        }
        blocks.push({ kind: "resource", type: PHONE_PROVIDER, label: tsLabelToTfLabel(key), attrs: {
                name: phoneProvider.name,
                twilio: { account_id: accountId, auth_token: authToken },
            } });
        for (const [name, block] of resourceVariables)
            variables.set(name, block);
    }
    return [...variables.values(), ...blocks];
}
